// Port of all 16 independent round-two cases. Oracle-dependent cases now assert
// the SAFE replacement semantics; original authority demonstrations are not counted as fixes.
fn r2_setup()->Contract {near_sdk::mock::with_mocked_blockchain(|b|{b.take_storage();});setup()}
fn r2_remove_binding(){collateral().remove(&"k1".into());}
#[test] fn round2_transfer_result_byte_bound_and_malformed_matrix(){
 let mut cases=vec![(PromiseResult::Failed,false),(PromiseResult::Successful(b"false".to_vec()),true),
 (PromiseResult::Successful(b"true".to_vec()),false)];
 for len in [31usize,32,33,32768,2_000_005] {
   let mut v=vec![b' ';len-5];v.extend_from_slice(b"false");cases.push((PromiseResult::Successful(v),len<=32));
 }
 for v in [b"".to_vec(),b"null".to_vec(),b"0".to_vec(),b"{}".to_vec(),b"[false]".to_vec(),b"false junk".to_vec(),vec![0xff,0xfe],b"False".to_vec()] {cases.push((PromiseResult::Successful(v),false));}
 for (r,kept) in cases {let mut c=r2_setup();ctx("alice.near",1,NOW);let _=c.nft_transfer_call(a("receiver.near"),"k1".into(),None,None,"".into());let epoch=c.nft_settlement_epoch("k1".into());
 result(r,NOW);assert_eq!(c.resolve_transfer_call("k1".into(),epoch),kept);
 assert!(!c.get_control_state("k1".into()).transfer_pending);assert_eq!(c.pending_return_count(a("alice.near")),0);
 assert_eq!(c.nft_token("k1".into()).unwrap().owner_id, a(if kept{"receiver.near"}else{"alice.near"}));}
}
#[test] fn round2_policy_malformed_oversized_results_never_unlock_or_release_binding(){
 for bytes in [vec![],b"true".to_vec(),vec![0xff;20],vec![b' ';32_769],vec![b' ';2_000_000]] {
 let mut c=r2_setup();r2_remove_binding();let n=registration(&mut c);result(PromiseResult::Failed,NOW);let _=c.on_collateral_stored("k1".into(),n);
 result(PromiseResult::Successful(bytes.clone()),NOW);assert!(!c.on_collateral_checked("k1".into(),n));assert!(c.get_collateral_binding("k1".into()).is_some());assert_eq!(c.get_payout_credit(a("minter.near")).0,N/10-COLLATERAL_STORAGE_DEPOSIT);
 let mut c=r2_setup();open(&mut c);let l=c.get_loan("k1".into()).unwrap();result(PromiseResult::Successful(vec![]),NOW);let _=c.on_policy_action("k1".into(),l.nonce,l.policy_sequence);
 result(PromiseResult::Successful(bytes),NOW);assert!(!c.on_loan_policy("k1".into(),l.nonce,l.policy_sequence));assert!(c.get_loan("k1".into()).unwrap().policy_busy);assert_eq!(c.get_loan("k1".into()).unwrap().state,LoanState::Freezing);
 }
}

#[test]fn round2_port_round1_failed_registration_is_retryable_and_fully_credited(){let mut c=r2_setup();r2_remove_binding();let n=registration(&mut c);result(PromiseResult::Failed,NOW);let _=c.on_collateral_stored("k1".into(),n);result(PromiseResult::Successful(b"null".to_vec()),NOW);assert!(!c.on_collateral_checked("k1".into(),n));assert!(c.get_collateral_binding("k1".into()).is_none());assert_eq!(c.get_payout_credit(a("minter.near")).0,N/10);assert_ne!(registration(&mut c),n);}
#[test]fn round2_port_round1_lender_with_key_rejected(){let mut c=r2_setup();ctx("minter.near",N/10,NOW);c.nft_mint("k2".into(),a("lender.near"),1,TokenMetadata::default());open(&mut c);settle_policy(&mut c,true,NOW);rejected(||fund(&mut c));assert_eq!(c.get_loan("k1".into()).unwrap().state,LoanState::Offered);}
#[test]fn round2_port_round1_unknown_token_rejects(){let c=r2_setup();rejected(||{c.get_control_state("does-not-exist".into());});}
#[test]fn round2_missing_policy_callback_remains_unknown_despite_matching_snapshot(){let mut c=r2_setup();open(&mut c);let l=c.get_loan("k1".into()).unwrap();ctx("anyone.near",0,NOW);rejected(||{let _=c.reconcile_loan_policy("k1".into(),l.nonce);});result(policy(true),NOW);assert!(!c.on_loan_policy("k1".into(),l.nonce,l.policy_sequence));assert_eq!(c.get_loan("k1".into()).unwrap().state,LoanState::Freezing);}
#[test]fn round2_missing_principal_callback_is_eliminated_by_atomic_credit(){let mut c=r2_setup();open(&mut c);settle_policy(&mut c,true,NOW);fund(&mut c);assert_eq!(c.get_loan("k1".into()).unwrap().state,LoanState::DisbursementPending);assert_eq!(c.get_payout_credit(a("alice.near")).0,N);assert!(get_created_receipts().is_empty());}
#[test]fn round2_principal_both_late_callback_results_cannot_change_credit_or_debt(){for success in [true,false]{let mut c=r2_setup();open(&mut c);settle_policy(&mut c,true,NOW);fund(&mut c);result(if success{PromiseResult::Successful(vec![])}else{PromiseResult::Failed},NOW);assert_eq!(c.get_payout_credit(a("alice.near")).0,N);assert_eq!(c.get_payout_credit(a("lender.near")).0,0);assert_eq!(c.get_loan("k1".into()).unwrap().state,LoanState::DisbursementPending);}}
#[test]fn round2_registration_read_callback_orders_and_duplicates_are_safe(){for success in [true,false]{let mut c=r2_setup();r2_remove_binding();let n=registration(&mut c);result(policy(false),NOW);assert!(!c.on_collateral_checked("k1".into(),n));result(if success{PromiseResult::Successful(vec![])}else{PromiseResult::Failed},NOW);let _=c.on_collateral_stored("k1".into(),n);let before=c.get_payout_credit(a("minter.near"));let _=c.on_collateral_stored("k1".into(),n);assert_eq!(c.get_payout_credit(a("minter.near")),before);result(if success{policy(false)}else{PromiseResult::Successful(b"null".to_vec())},NOW);let _=c.on_collateral_checked("k1".into(),n);assert_eq!(c.get_payout_credit(a("minter.near")).0,if success{0}else{N/10});}}
#[test]fn round2_payout_real_callback_orders_and_duplicate_results_never_double_credit(){for success in [true,false]{let mut c=r2_setup();active(&mut c);ctx("alice.near",terms().repayment.0,NOW);let _=c.repay_loan("k1".into(),U64(1));ctx("lender.near",1,NOW);let _=c.claim_payout();let p=c.get_pending_payout(a("lender.near")).unwrap();result(if success{PromiseResult::Successful(vec![])}else{PromiseResult::Failed},NOW);assert_eq!(c.on_payout(a("lender.near"),p.nonce),success);let before=c.get_payout_credit(a("lender.near"));assert!(!c.on_payout(a("lender.near"),p.nonce));assert_eq!(c.get_payout_credit(a("lender.near")),before);assert_eq!(before.0,if success{0}else{p.amount.0});}}
#[test]fn round2_treasury_real_callback_and_duplicates_conserve_attribution(){for success in [true,false]{let mut c=r2_setup();ctx("owner.near",2*N,RECOVERY_UNLOCK_NS);c.fund_treasury();ctx("recovery.near",1,RECOVERY_UNLOCK_NS);let _=c.recover_treasury(U128(N));let p=config_required().treasury_pending.unwrap();result(if success{PromiseResult::Successful(vec![])}else{PromiseResult::Failed},RECOVERY_UNLOCK_NS);assert_eq!(c.on_treasury_recovered(p.nonce),success);assert!(!c.on_treasury_recovered(p.nonce));assert_eq!(config_required().treasury_available.0,if success{N}else{2*N});}}
#[test]fn round2_transfer_timeout_resolver_orders_and_committed_acceptance_are_safe(){for accepted in [true,false]{for timeout_first in [true,false]{let mut c=r2_setup();ctx("alice.near",1,NOW);let _=c.nft_transfer_call(a("receiver.near"),"k1".into(),None,None,"".into());let epoch=c.nft_settlement_epoch("k1".into());if timeout_first{ctx("anyone.near",0,NOW+TRANSFER_RESTORE_DELAY_NS);assert!(!c.restore_expired_transfer("k1".into(),epoch));}result(PromiseResult::Successful(if accepted{b"false".to_vec()}else{b"true".to_vec()}),NOW+TRANSFER_RESTORE_DELAY_NS);assert_eq!(c.resolve_transfer_call("k1".into(),epoch),accepted&&!timeout_first);ctx("anyone.near",0,NOW+2*TRANSFER_RESTORE_DELAY_NS);rejected(||{c.restore_expired_transfer("k1".into(),epoch);});assert_eq!(c.nft_token("k1".into()).unwrap().owner_id,a(if accepted&&!timeout_first{"receiver.near"}else{"alice.near"}));assert_eq!(c.pending_return_count(a("alice.near")),0);}}}
#[test]fn round2_policy_overlapping_reads_and_old_generations_are_harmless(){let mut c=r2_setup();open(&mut c);let old=c.get_loan("k1".into()).unwrap();let old_policy=policy(true);result(PromiseResult::Successful(vec![]),NOW);let _=c.on_policy_action("k1".into(),old.nonce,old.policy_sequence);result(policy(true),NOW);assert!(c.on_loan_policy("k1".into(),old.nonce,old.policy_sequence));ctx("alice.near",1,NOW);let _=c.cancel_loan("k1".into(),old.nonce);let new=c.get_loan("k1".into()).unwrap();assert!(new.policy_sequence.0>old.policy_sequence.0);result(old_policy,NOW);assert!(!c.on_loan_policy("k1".into(),old.nonce,old.policy_sequence));assert!(c.get_loan("k1".into()).unwrap().policy_busy);}
#[test]fn round2_false_principal_failure_cannot_cancel_backed_credit_or_lien(){let mut c=r2_setup();open(&mut c);settle_policy(&mut c,true,NOW);fund(&mut c);ctx("attacker.near",0,NOW);rejected(||{c.restore_expired_transfer("k1".into(),U64(1));});assert_eq!(c.get_payout_credit(a("lender.near")).0,0);assert_eq!(c.get_payout_credit(a("alice.near")).0,N);assert_eq!(c.get_loan("k1".into()).unwrap().state,LoanState::DisbursementPending);}
#[test]fn round2_paid_credit_cannot_be_restored_three_times_by_any_outcome_signer(){let mut c=r2_setup();active(&mut c);ctx("alice.near",terms().repayment.0,NOW);let _=c.repay_loan("k1".into(),U64(1));ctx("lender.near",1,NOW);let _=c.claim_payout();let p=c.get_pending_payout(a("lender.near")).unwrap();for _ in 0..3{ctx("attacker.near",0,NOW+1000*SECOND);rejected(||{c.on_payout(a("lender.near"),p.nonce);});assert_eq!(c.get_payout_credit(a("lender.near")).0,0);}result(PromiseResult::Successful(vec![]),NOW);assert!(c.on_payout(a("lender.near"),p.nonce));ctx("lender.near",1,NOW);rejected(||{let _=c.claim_payout();});}
#[test]fn round2_no_signer_can_override_a_live_nft_return_request(){let mut c=r2_setup();ctx("alice.near",1,NOW);let _=c.nft_transfer_call(a("receiver.near"),"k1".into(),None,None,"".into());let epoch=c.nft_settlement_epoch("k1".into());ctx("attacker.near",0,NOW);rejected(||{c.restore_expired_transfer("k1".into(),epoch);});result(PromiseResult::Successful(b"true".to_vec()),NOW);assert!(!c.resolve_transfer_call("k1".into(),epoch));assert_eq!(c.nft_token("k1".into()).unwrap().owner_id,a("alice.near"));}
